const RC=META.parts.length+1, QZ=RC+1, LS=RC+2, OUT=RC+3;

/* ---------- drawing helpers for this lesson (prefixed SG_ so they never clash with engine globals) ---------- */
const SG_F='font-family="Nunito Sans, sans-serif"';
const SG_T=(x,y,t,o={})=>`<text x="${x}" y="${y}" ${SG_F} font-size="${o.fs||24}" font-weight="${o.fw||600}" text-anchor="${o.a||'start'}" fill="${o.fill||'#18213A'}">${t}</text>`;
const SG_L=(x1,y1,x2,y2,col='#5C6577',w=2,ex='')=>`<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${col}" stroke-width="${w}" stroke-linecap="round" ${ex}/>`;
const SG_box=(x,y,w,h,o={})=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${o.r??14}" fill="${o.fill||'#FFFFFF'}" stroke="${o.st||'#CED4DA'}" stroke-width="${o.sw||2}"/>`;
const SG_curve=(f,t0,t1,x0,x1,yc,k,col,w=4,n=160)=>{let p=[];for(let i=0;i<=n;i++){const t=t0+(t1-t0)*i/n;p.push(`${(x0+(x1-x0)*i/n).toFixed(1)},${(yc-k*f(t)).toFixed(1)}`)}return `<polyline points="${p.join(' ')}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linejoin="round" stroke-linecap="round"/>`};
const SG_stems=(v,x0,dx,yc,k,col,r=7)=>v.map((q,i)=>{const x=x0+i*dx,y=yc-k*q;return SG_L(x,yc,x,y.toFixed(1),col,4)+`<circle cx="${x}" cy="${y.toFixed(1)}" r="${r}" fill="${col}"/>`}).join('');
const SG_arrow=(x1,y1,x2,y2,col='#18213A',w=3)=>{const a=Math.atan2(y2-y1,x2-x1),h=14;return SG_L(x1,y1,(x2-h*.6*Math.cos(a)).toFixed(1),(y2-h*.6*Math.sin(a)).toFixed(1),col,w)+`<polygon points="${x2},${y2} ${(x2-h*Math.cos(a)+h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)-h*.5*Math.cos(a)).toFixed(1)} ${(x2-h*Math.cos(a)-h*.5*Math.sin(a)).toFixed(1)},${(y2-h*Math.sin(a)+h*.5*Math.cos(a)).toFixed(1)}" fill="${col}"/>`};
const SG_X=(x,y,s,col,w=5)=>SG_L(x-s,y-s,x+s,y+s,col,w)+SG_L(x-s,y+s,x+s,y-s,col,w);
const SG_O=(x,y,r,col)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="#FFFFFF" stroke="${col}" stroke-width="4"/>`;
const SG_sup=(a,b)=>`${a}<tspan baseline-shift="super" font-size="65%">${b}</tspan>`;
/* a shaded z-plane region: inner and outer radii (outer null = to the edge of the w x h box) */
const SG_zreg=(cx,cy,r1,r2,w,h,col)=>{const C=r=>`M${cx+r},${cy} A${r},${r} 0 1 0 ${cx-r},${cy} A${r},${r} 0 1 0 ${cx+r},${cy} Z`;
 const outer=r2==null?`M${cx-w/2},${cy-h/2} H${cx+w/2} V${cy+h/2} H${cx-w/2} Z`:C(r2);return `<path d="${outer} ${r1>0?C(r1):''}" fill="${col}" fill-opacity=".22" fill-rule="evenodd" stroke="none"/>`};
const SG_axes=(cx,cy,w,h)=>SG_L(cx-w/2,cy,cx+w/2,cy,'#ADB5BD',2)+SG_L(cx,cy-h/2,cx,cy+h/2,'#ADB5BD',2);
const SG_ring=(cx,cy,r,col,ex='stroke-dasharray="7 6"')=>`<circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="${col}" stroke-width="3" ${ex}/>`;
/* computed data */
const SG_x4=[1,2,3,4];
const SG_dtft=w=>{let re=0,im=0;SG_x4.forEach((v,n)=>{re+=v*Math.cos(w*n);im-=v*Math.sin(w*n)});return Math.hypot(re,im)};   // |X(e^jw)| of 1,2,3,4
const SG_Xmag=[0,1,2,3].map(k=>SG_dtft(k*Math.PI/2));        // 10, 2.83, 2, 2.83
const SG_X8=[0,1,2,3,4,5,6,7].map(k=>SG_dtft(k*Math.PI/4));   // the 8-point samples
const SG_Xz=r=>Math.abs(r*(2*r-5/6)/((r-1/3)*(r-1/2)));        // |X(z)| of the worked example on the real axis

